package co.edu.corhuila.rutasur.controller;
import co.edu.corhuila.rutasur.dto.request.ServicioExperienciaRequest; import co.edu.corhuila.rutasur.dto.response.ServicioExperienciaResponse; import co.edu.corhuila.rutasur.service.ServicioExperienciaServicio; import jakarta.validation.Valid; import java.util.List; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequiredArgsConstructor @RequestMapping("/api/v1") public class ServicioExperienciaController {private final ServicioExperienciaServicio servicio;
 @GetMapping("/public/experiencias/{experienciaId}/servicios") public ResponseEntity<List<ServicioExperienciaResponse>> listar(@PathVariable Long experienciaId){return ResponseEntity.ok(servicio.listar(experienciaId));}
 @PostMapping("/experiencias/{experienciaId}/servicios") @PreAuthorize("hasRole('ADMINISTRADOR')") public ResponseEntity<ServicioExperienciaResponse> crear(@PathVariable Long experienciaId,@Valid @RequestBody ServicioExperienciaRequest solicitud){return ResponseEntity.status(HttpStatus.CREATED).body(servicio.crear(experienciaId,solicitud));}
 @PutMapping("/experiencias/{experienciaId}/servicios/{id}") @PreAuthorize("hasRole('ADMINISTRADOR')") public ResponseEntity<ServicioExperienciaResponse> actualizar(@PathVariable Long experienciaId,@PathVariable Long id,@Valid @RequestBody ServicioExperienciaRequest solicitud){return ResponseEntity.ok(servicio.actualizar(experienciaId,id,solicitud));}
 @DeleteMapping("/experiencias/{experienciaId}/servicios/{id}") @PreAuthorize("hasRole('ADMINISTRADOR')") public ResponseEntity<Void> inactivar(@PathVariable Long experienciaId,@PathVariable Long id){servicio.inactivar(experienciaId,id);return ResponseEntity.noContent().build();}}
